H.background();
// Conservation of angular momentum:  L = I * omega = constant
// A skater pulls arms in (smaller r -> smaller I) and spins faster.
const m = P.m, L = P.L;
// radius oscillates between a wide and a tucked arm position
const rMax = 3.0, rMin = 0.8;
const r = rMin + (rMax - rMin) * (0.5 + 0.5 * Math.cos(t * 0.9));
const I = m * r * r;                       // point-mass moment of inertia
const omega = L / Math.max(1e-6, I);       // omega from conserved L
const KE = 0.5 * I * omega * omega;        // rotational kinetic energy
const cx = H.W * 0.40, cy = H.H * 0.55;
const scale = 42;                          // pixels per meter
// central axis
H.circle(cx, cy, 5, { fill: H.colors.sub });
// the spinning mass on its arm
const ang = t * omega * 0.25;              // visual spin (slowed for clarity)
const px = cx + r * scale * Math.cos(ang);
const py = cy - r * scale * Math.sin(ang);
H.line(cx, cy, px, py, { color: H.colors.axis, width: 2 });
// circular path
H.circle(cx, cy, r * scale, { stroke: H.colors.grid, width: 1.2 });
H.circle(px, py, 11, { fill: H.colors.accent });
// tangential velocity arrow  v = omega * r
const vmag = omega * r;
const tx = -Math.sin(ang), ty = -Math.cos(ang);
H.arrow(px, py, px + tx * vmag * 7, py + ty * vmag * 7, { color: H.colors.warn, width: 2.5 });
// labels
H.text("Angular momentum:  L = I·omega = const", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("pull the mass in -> I drops -> omega rises (L fixed)", 24, 52, { color: H.colors.sub, size: 13 });
H.text("r = " + r.toFixed(2) + " m    I = " + I.toFixed(2) + " kg·m^2", 24, H.H - 56, { color: H.colors.sub, size: 13 });
H.text("omega = " + omega.toFixed(2) + " rad/s    L = " + L.toFixed(2) + " kg·m^2/s", 24, H.H - 36, { color: H.colors.good, size: 13 });
H.text("KE_rot = ½·I·omega^2 = " + KE.toFixed(2) + " J", 24, H.H - 16, { color: H.colors.accent2, size: 13 });
H.legend([{ label: "mass", color: H.colors.accent }, { label: "v = omega·r", color: H.colors.warn }], H.W - 170, 28);
